package com.google.javascript.rhino.jstype;

import com.google.common.collect.Maps;
import com.google.javascript.rhino.Node;
import com.google.javascript.rhino.jstype.JSTypeNative;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class RecordTypeBuilder_build_TriageGen0Test {

    private JSTypeRegistry registry;
    private JSType objectType;

    @Before
    public void setUp() {
        registry = mock(JSTypeRegistry.class);
        objectType = mock(JSType.class);
        when(registry.getNativeObjectType(JSTypeNative.OBJECT_TYPE)).thenReturn(objectType);
    }

    @Test
    public void testBuild_WhenEmpty_ReturnsObjectType() {
        // Arrange: An empty builder (isEmpty is true by default if no properties added)
        RecordTypeBuilder builder = new RecordTypeBuilder(registry);

        // Act
        JSType result = builder.build();

        // Assert
        assertEquals("Should return the native object type when builder is empty", objectType, result);
    }

    @Test
    public void testBuild_WhenNotEmpty_ReturnsRecordType() {
        // Arrange: Add a property to make the builder non-empty
        RecordTypeBuilder builder = new RecordTypeBuilder(registry);
        String propName = "foo";
        JSType propType = mock(JSType.class);
        Node propNode = mock(Node.class);

        builder.addProperty(propName, propType, propNode);

        // Act
        JSType result = builder.build();

        // Assert
        assertTrue("Result should be an instance of RecordType", result instanceof RecordType);

        RecordType recordType = (RecordType) result;
        // Accessing internal properties via public API if available, 
        // or verifying the structure via the RecordType behavior.
        // Since we can't easily access the private 'properties' map without reflection,
        // we verify it is not the object type.
        assertFalse("Result should not be the native object type", result == objectType);
    }

    @Test
    public void testBuild_WithMultipleProperties_ReturnsRecordTypeWithAllProperties() {
        // Arrange
        RecordTypeBuilder builder = new RecordTypeBuilder(registry);
        JSType type1 = mock(JSType.class);
        JSType type2 = mock(JSType.class);
        Node node1 = mock(Node.class);
        Node node2 = mock(Node.class);

        builder.addProperty("a", type1, node1);
        builder.addProperty("b", type2, node2);

        // Act
        JSType result = builder.build();

        // Assert
        assertTrue(result instanceof RecordType);
        RecordType recordType = (RecordType) result;

        // In Rhino, RecordType properties are usually accessed via getProperty(name)
        assertEquals("Property 'a' should match type1", type1, recordType.getProperty("a"));
        assertEquals("Property 'b' should match type2", type2, recordType.getProperty("b"));
    }
}
